      "label": "Pasal 349",
      "bagian_dokumen": "BATANG_TUBUH",
      "hierarki": "PASAL",
      "parent_bab": "BAB XI",
      "parent_bagian": "Bagian Ketiga",
      "teks": "Pasal 349.",
      "target_induk": "undang-undang-9-2015",
      "parent_pasal_perubahan": "Pasal 176"
    },
    {
      "tipe": "PASAL",
